"""Fast SHA-256 solver using CPython's direct OpenSSL binding."""
import hashlib


class Solver:
    def solve(self, problem, **kwargs):
        # The one-shot API avoids construction of cryptography's Hash wrapper and
        # dispatches directly to OpenSSL's optimized SHA-256 implementation.
        return {"digest": hashlib.sha256(problem["plaintext"]).digest()}

